1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
3	import { createEncounterConfig, encounterRules } from "@pirate-sea-race/simulation/encounters";
4	import { ImpairmentProxy, logFromBundles, replayRecordedDuel, type HeadlessClient, type Impairment } from "@pirate-sea-race/test-tools";
5	import { attacker, defender, expectWithinBudget, opponentChanges, PLAY_FRAMES, SETTLE_FRAMES, type ScenarioReport } from "./harness.js";
6	import { objectiveRules } from "@pirate-sea-race/simulation/objectives";
7	import { brawler, collectAt, dockFor, grapple, pairInRange, resultOf, roomOf, TEST_SOURCE_LAYOUT, TILE, tracker } from "./seaDuelSetup.js";
8	
9	/**
10	 * The impairment harness (`harness.ts`) on a duel inside a match room (§14): two players join a match through their
11	 * own impaired proxies, one grapples the other, and they fight the harness's scripted duel over the match room's
12	 * socket, with the same budget as the standalone duel room. The draw's return is here too: its mirrored fight needs
13	 * both fighters' inputs on time, so it runs alone rather than beside the other duels at sea.
14	 */
15	let server: RunningGameServer;
16	let endpoint: string;
17	const rules = createEncounterConfig();
18	
19	beforeAll(async () => {
20	  // The test source layout and one-second holds (test-only), so the draw's players carry rubbings into it.
21	  const matchTuning = { sourceLayout: TEST_SOURCE_LAYOUT.map((types) => [...types]), objectives: { ...objectiveRules, collectTicks: 20 } };
22	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning });
23	  endpoint = `http://127.0.0.1:${server.port}`;
24	});
25	
26	afterAll(async () => {
27	  await server.close();
28	});
29	
30	async function runScenario(scenario: string, impairment: Impairment, seed: number): Promise<ScenarioReport> {
31	  const proxies = await Promise.all([ImpairmentProxy.start(server.port, impairment, seed), ImpairmentProxy.start(server.port, impairment, seed + 1)]);
32	  const joined: HeadlessClient[] = [];
33	  try {
34	    const { host, guest } = await pairInRange(endpoint, (client) => void joined.push(client), { endpoints: proxies.map((proxy) => proxy.endpoint) });
35	    host.fighter.play((frame) => (frame <= PLAY_FRAMES ? attacker(frame, host.fighter.duel!) : 0));
36	    guest.fighter.play((frame) => (frame <= PLAY_FRAMES ? defender(frame, guest.fighter.duel!) : 0));
37	    await grapple(host, guest);
38	    await host.waitFor(() => host.fighter.phase === "fighting", 8000);
39	    const players = [host.fighter, guest.fighter] as const;
40	    for (const player of players) await player.waitForConfirmed(PLAY_FRAMES + SETTLE_FRAMES, 30_000);
41	    const duel = roomOf(host).seaDuelDiagnostics(host.sessionId)!;
42	
43	    // Determinism on top of the live hash checks: the pairs each client received replay to the server's state.
44	    for (const player of players) {
45	      const log = logFromBundles(player.bundles);
46	      const replayed = await replayRecordedDuel(log, { seed: duel.seed });
47	      const fromServer = await replayRecordedDuel({ ...duel.inputLog, inputs: duel.inputLog.inputs.slice(0, log.inputs.length) }, { seed: duel.seed });
48	      expect(log.inputs.length).toBeGreaterThanOrEqual(PLAY_FRAMES + SETTLE_FRAMES);
49	      expect(replayed.hash).toBe(fromServer.hash);
50	    }
51	    const through = PLAY_FRAMES + SETTLE_FRAMES;
52	    const pair = <T>(pick: (player: (typeof players)[number], index: 0 | 1) => T): [T, T] => [pick(players[0], 0), pick(players[1], 1)];
53	    return {
54	      scenario,
55	      inputDelay: duel.inputDelay,
56	      corrections: pair((player) => player.stats!.corrections),
57	      correctionBound: pair((player, index) => opponentChanges(player, through) + player.stats!.substitutedFrames[index]),
58	      substituted: [duel.authority.repeated[0] + duel.authority.neutral[0], duel.authority.repeated[1] + duel.authority.neutral[1]],
59	      hashChecks: pair((player) => player.stats!.hashChecks),
60	      desyncs: pair((player) => player.stats!.desyncs),
61	      deepestReplay: pair((player) => player.stats!.deepestReplay),
62	      rateLimited: [duel.dropped["0"]!["rate-limited"], duel.dropped["1"]!["rate-limited"]],
63	      lostMessages: proxies[0].stats.lost[0] + proxies[0].stats.lost[1] + proxies[1].stats.lost[0] + proxies[1].stats.lost[1],
64	    };
65	  } finally {
66	    await Promise.all(joined.map((client) => client.leave()));
67	    await Promise.all(proxies.map((proxy) => proxy.close()));
68	  }
69	}
70	
71	describe("a duel at sea through the impairment harness", () => {
72	  it("keeps both fighters on the server's state with 80 ms round trip, 20 ms jitter, 1% loss", async ({ annotate }) => {
73	    const report = await runScenario("at sea, 80 ms round trip, 20 ms jitter, 1% loss", { rttMs: 80, jitterMs: 20, loss: 0.01 }, 31);
74	    console.log(`duel harness: ${JSON.stringify(report)}`);
75	    await annotate(
76	      `${report.scenario}: input delay ${report.inputDelay}; corrections ${report.corrections.join("/")} (bound ${report.correctionBound.join("/")}); ` +
77	        `server substitutions ${report.substituted.join("/")}; hash checks ${report.hashChecks.join("/")}, desyncs ${report.desyncs.join("/")}; ` +
78	        `deepest replay ${report.deepestReplay.join("/")} frames; rate-limited drops ${report.rateLimited.join("/")}; lost messages ${report.lostMessages}`,
79	    );
80	    expectWithinBudget(report);
81	    for (const checks of report.hashChecks) expect(checks).toBeGreaterThanOrEqual(175);
82	    expect(report.lostMessages).toBeGreaterThan(0);
83	    // The impaired link gets a longer input delay than a local one's minimum.
84	    expect(report.inputDelay).toBeGreaterThan(3);
85	  }, 60_000);
86	});
87	
88	describe("a draw at sea (§6)", () => {
89	  it("returns both players of a draw to separate nearby points with 8 s of protection, and moves no rubbing and no gold", async ({ onTestFinished }) => {
90	    const track = tracker(onTestFinished);
91	    const { host, guest } = await pairInRange(endpoint, track);
92	    const at = { host: host.ship()!, guest: guest.ship()! };
93	    // Each carries a rubbing the other lacks into the fight.
94	    await Promise.all([collectAt(host, endpoint, dockFor("sun"), "sun"), collectAt(guest, endpoint, dockFor("moon"), "moon")]);
95	    await host.placeShip(endpoint, { tileX: Math.floor(at.host.x / TILE), tileY: Math.floor(at.host.y / TILE), heading: at.host.heading });
96	    await guest.placeShip(endpoint, { tileX: Math.floor(at.guest.x / TILE), tileY: Math.floor(at.guest.y / TILE), heading: at.guest.heading });
97	    await host.waitFor(() => host.ship(guest.sessionId) !== undefined);
98	    await grapple(host, guest);
99	    // The mirrored fight: both swing on the same frames, so both fall on the same frame.
100	    host.fighter.play(brawler(0));
101	    guest.fighter.play(brawler(1));
102	    expect(await resultOf(host, guest)).toEqual({ phase: "over", winner: -1, reason: "double-ko" });
103	    for (const client of [host, guest]) await client.waitFor(() => client.status()?.protection === "draw", 2000);
104	    const expected = rules.modes.ship.rules.separateReturn({
105	      encounter: { x: Math.floor((at.host.x + at.guest.x) / 2), y: Math.floor((at.host.y + at.guest.y) / 2) },
106	      players: [at.host, at.guest],
107	      minSeparation: rules.drawReturnMinSeparation,
108	      maxDistance: rules.drawReturnMaxDistance,
109	    });
110	    await host.waitFor(() => host.ship()!.x === expected[0].x && host.ship()!.y === expected[0].y, 2000);
111	    await guest.waitFor(() => guest.ship()!.x === expected[1].x && guest.ship()!.y === expected[1].y, 2000);
112	    expect(Math.hypot(expected[0].x - expected[1].x, expected[0].y - expected[1].y)).toBeGreaterThanOrEqual(rules.drawReturnMinSeparation);
113	    expect(host.status()!.protectedUntil).toBe(guest.status()!.protectedUntil);
114	    expect(host.status()!.protectedUntil - host.worldTick).toBeLessThanOrEqual(encounterRules.drawProtectionTicks);
115	    expect(host.status()!.protectedUntil - host.worldTick).toBeGreaterThan(encounterRules.drawProtectionTicks - 20);
116	    // Both back in the world, and in each other's sight.
117	    for (const client of [host, guest]) expect(client.status()?.mode).toBe("sea");
118	    await host.waitFor(() => host.ship(guest.sessionId) !== undefined);
119	    // §4: a draw moves nothing. The ledger settled it on the fight's result, and each keeps its rubbing and gold.
120	    expect(roomOf(host).ledgerState.duels[0]).toMatchObject({ phase: "settled", result: { outcome: "draw" }, settlement: { choice: "none", gold: 0 } });
121	    expect(host.objectives()).toMatchObject({ rubbings: ["sun"], gold: 50, settledRole: "draw", stolen: "", goldChange: 0 });
122	    expect(guest.objectives()).toMatchObject({ rubbings: ["moon"], gold: 50, settledRole: "draw", stolen: "", goldChange: 0 });
123	  }, 30_000);
124	});
